para('\u0411\u043b\u043e\u043a \u0438\u0437 256 \u043f\u043e\u0442\u043e\u043a\u043e\u0432 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0432\u043e\u0441\u0435\u043c\u044c \u0432\u0430\u0440\u043f\u043e\u0432. \u041a\u0430\u0436\u0434\u044b\u0439 \u0432\u0430\u0440\u043f \u043a\u043e\u043b\u043b\u0435\u043a\u0442\u0438\u0432\u043d\u043e \u0432\u044b\u0447\u0438\u0441\u043b\u044f\u0435\u0442 \u043f\u043b\u0438\u0442\u043a\u0443 16x16; \u0431\u043b\u043e\u043a \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442 32x64 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430. \u0421\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u044e\u0442\u0441\u044f \u043f\u043b\u0438\u0442\u043a\u0438 A \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u043c 32x16 \u0438 B \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u043c 16x64. \u0414\u0432\u0430 \u0431\u0430\u0440\u044c\u0435\u0440\u0430 \u0437\u0430\u0449\u0438\u0449\u0430\u044e\u0442 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0443 \u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u043e\u0431\u0449\u0435\u0439 \u043f\u0430\u043c\u044f\u0442\u0438. \u0410\u0434\u0440\u0435\u0441\u0430 \u0434\u043b\u044f WMMA \u0432\u044b\u0440\u043e\u0432\u043d\u0435\u043d\u044b \u043d\u0430 32 \u0431\u0430\u0439\u0442\u0430; \u0448\u0430\u0433\u0438 \u0441\u0442\u0440\u043e\u043a A/B \u0440\u0430\u0432\u043d\u044b 16/64 half-\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u043c. \u0418\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441 WMMA \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0440\u0430\u0437\u043c\u0435\u0440\u044b, \u043a\u0440\u0430\u0442\u043d\u044b\u0435 16; \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0435 \u0440\u0430\u0437\u043c\u0435\u0440\u044b \u043e\u0442\u043a\u043b\u043e\u043d\u044f\u044e\u0442\u0441\u044f \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430.')
