para('CUDA Events \u0438\u0437\u043c\u0435\u0440\u044f\u044e\u0442 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b \u0432\u043e\u043a\u0440\u0443\u0433 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u043a\u0435\u0440\u043d\u0435\u043b\u0430. \u0412\u044b\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430 \u0432\u043d\u0443\u0442\u0440\u0438 operator*, \u043a\u043e\u043d\u0432\u0435\u0440\u0442\u0430\u0446\u0438\u044f \u0432\u0445\u043e\u0434\u043e\u0432, \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0438 CPU/GPU \u0438 \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u043f\u0430\u043c\u044f\u0442\u0438 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u044b. \u0422\u0440\u0438 \u043f\u0440\u043e\u0433\u0440\u0435\u0432\u043e\u0447\u043d\u044b\u0445 \u0432\u044b\u0437\u043e\u0432\u0430, \u043f\u044f\u0442\u044c \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u043d\u0430 \u0440\u0430\u0437\u043c\u0435\u0440, \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 \u0432\u0440\u0435\u043c\u044f \u0441\u0435\u0440\u0438\u0438 0.2 \u0441. \u0422\u0430\u0431\u043b\u0438\u0446\u0430 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u043c\u0435\u0434\u0438\u0430\u043d\u044b, \u043f\u043e\u043b\u043e\u0441\u0430 \u043d\u0430 \u0433\u0440\u0430\u0444\u0438\u043a\u0435 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 - \u043c\u0438\u043d\u0438\u043c\u0443\u043c \u0438 \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c \u0441\u0440\u0435\u0434\u043d\u0438\u0445 \u0432\u0440\u0435\u043c\u0451\u043d \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432, \u043d\u0435 \u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b.')
para('\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435: \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0438\u0439 shared-memory FP32 / \u043d\u043e\u0432\u044b\u0439 WMMA FP16->FP32. \u0412\u0445\u043e\u0434\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b \u0438 \u0442\u043e\u0447\u043d\u043e \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u043c\u044b \u0432 half, \u043d\u043e \u0444\u043e\u0440\u043c\u0430\u0442\u044b \u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u044e\u0442\u0441\u044f. \u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c: shared-memory \u0441 FP16-\u0432\u0445\u043e\u0434\u0430\u043c\u0438 \u0438 FP32-\u043d\u0430\u043a\u043e\u043f\u043b\u0435\u043d\u0438\u0435\u043c. \u0422\u0430\u043a\u043e\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u0435 half->float \u0432\u043d\u0443\u0442\u0440\u0438 \u043a\u0435\u0440\u043d\u0435\u043b\u0430. \u042d\u0442\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u0447\u0430\u0441\u0442\u0438, \u043d\u0435 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f.')
